corrected_code:
const express = require('express');
const { body, validationResult } = require('express-validator');
const mongoose = require('mongoose');

const app = express();
app.use(express.json());

const LoyaltyAccount = mongoose.model('LoyaltyAccount', new mongoose.Schema({
  userId: String,
  pointsBalance: Number
}));

const redeemRules = [
  body('accountId').isMongoId().withMessage('Valid account MongoDB ID required'),
  body('pointsToDeduct').isInt({ min: 100, max: 50000 }).withMessage('Points between 100 and 50,000 required')
];

app.post('/api/loyalty/points/redeem', redeemRules, async (req, res) => {
  if (!req.user || !req.user.id) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  const { accountId, pointsToDeduct } = req.body;

  // Ensure query enforces account ownership by authenticated user
  const account = await LoyaltyAccount.findOne({ _id: accountId, userId: req.user.id });
  if (!account) {
    return res.status(404).json({ error: 'Loyalty account not found or unauthorized' });
  }

  if (account.pointsBalance < pointsToDeduct) {
    return res.status(400).json({ error: 'Insufficient balance' });
  }

  account.pointsBalance -= pointsToDeduct;
  await account.save();

  res.json({ success: true, remaining: account.pointsBalance });
});

app.listen(6002);
